// features/vendor_lifecycle.feature: a certificate with an unreadable expiry date cannot be approved.
import { expect, expectStatus, test } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test(
    "a certificate whose expiry date could not be read cannot be approved",
    { tag: "@LIF-08" },
    async ({ apiAs }) => {
      // Arrange: a vendor in review whose insurance certificate has an unreadable expiry date.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

      const createResponse = await member.post("/api/vendors", {
        data: {
          name: `Expiry Vendor ${suffix}`,
          category: "services",
          contact_email: `ops+${suffix}@example.test`,
        },
      });
      const vendor = await expectStatus<{ id: string }>(createResponse, 201);

      // The certificate text carries the unreadable expiry value.
      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: {
            name: `certificate-${suffix}.txt`,
            mimeType: "text/plain",
            buffer: Buffer.from("Certificate of insurance. Expiry date: next spring.\n"),
          },
        },
      });
      const document = await expectStatus<{ id: string }>(uploadResponse, 201);

      // Wait for extraction to finish on the uploaded document.
      await expect
        .poll(async () => {
          const response = await member.get(`/api/documents/${document.id}`);
          const body = await expectStatus<{ status: string }>(response, 200);
          return body.status;
        })
        .not.toBe("processing");

      const submitResponse = await member.post(`/api/vendors/${vendor.id}/submit`);
      await expectStatus<{ status: string }>(submitResponse, 200);

      const extractionResponse = await member.get(`/api/documents/${document.id}/extraction`);
      const extraction = await expectStatus<{ id: string; status: string }>(extractionResponse, 200);
      expect(extraction.status).toBe("pending_review");

      // Act: the reviewer tries to approve the certificate extraction.
      const decisionResponse = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
        data: { decision: "approve" },
      });

      // Assert: the approval is refused and the extraction stays pending review.
      const body = await expectStatus<{ error: { code: string } }>(decisionResponse, 409);
      expect(body.error.code).toBe("insurance_expiry_missing");

      const afterResponse = await reviewer.get(`/api/documents/${document.id}/extraction`);
      const after = await expectStatus<{ status: string }>(afterResponse, 200);
      expect(after.status).toBe("pending_review");
    },
  );
});
